#include "CaptureStorage.h"
#include <LittleFS.h>
#include <ArduinoJson.h>
#include <algorithm>
#include "ArchiveFormat.h"
using ArchiveFormat::Header;
using ArchiveFormat::crc32;
static constexpr uint32_t MAGIC=ArchiveFormat::Magic;
static constexpr size_t RESERVE=70000;
String CaptureStorage::path(const String& id) const{return "/a/"+id+".rec";}
String CaptureStorage::queuePath(const String& id) const{return "/q/"+id+".pending";}
static bool validId(const String& id){if(!id.length()||id.length()>80)return false;for(size_t i=0;i<id.length();i++){char c=id[i];if(!((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='-'))return false;}return true;}
bool CaptureStorage::begin(){if(!LittleFS.begin(false))return false;LittleFS.mkdir("/a");LittleFS.mkdir("/q");File d=LittleFS.open("/a");File f=d.openNextFile();while(f){String name=f.name();f=d.openNextFile();if(name.endsWith(".tmp")){String id=name.substring(name.lastIndexOf('/')+1,name.length()-8);if(validId(id)&&LittleFS.exists(queuePath(id))&&!LittleFS.exists(path(id))){String target=path(id);if(LittleFS.rename(name,target)){CaptureRecord recovered;if(!readMeta(id,recovered)){LittleFS.rename(target,name);lost_++;}}else lost_++;}else if(!LittleFS.exists(queuePath(id)))LittleFS.remove(name);}}d=LittleFS.open("/q");f=d.openNextFile();while(f){String name=f.name();f=d.openNextFile();if(name.endsWith(".tmp")){LittleFS.remove(name);continue;}if(name.endsWith(".pending")){String id=name.substring(name.lastIndexOf('/')+1,name.length()-8);if(!LittleFS.exists(path(id))&&!LittleFS.exists(path(id)+".tmp")){LittleFS.remove(name);lost_++;}continue;}if(name.endsWith(".rec")){String id=name.substring(name.lastIndexOf('/')+1,name.length()-4);String target=path(id);if(validId(id)&&!LittleFS.exists(target)){if(!LittleFS.rename(name,target))continue;}else if(validId(id)){CaptureRecord r;if(!readMeta(id,r))continue;LittleFS.remove(name);}if(validId(id)&&LittleFS.exists(target)&&!LittleFS.exists(queuePath(id))){File marker=LittleFS.open(queuePath(id),"w");marker.close();}}}return true;}
size_t CaptureStorage::freeBytes(){return LittleFS.totalBytes()-LittleFS.usedBytes();}
size_t CaptureStorage::capacity(){return LittleFS.totalBytes();}
bool CaptureStorage::append(const CaptureRecord& r,const uint8_t* data,size_t n){if(!validId(r.id)||!data||!n||n>32768){lost_++;return false;}if(LittleFS.exists(path(r.id))||LittleFS.exists(queuePath(r.id))){lost_++;return false;}JsonDocument j;j["id"]=r.id;j["ip"]=r.ip;j["port"]=r.port;j["timestamp"]=r.timestamp;j["format"]=r.format;j["text"]=r.text;j["incomplete"]=r.incomplete;String meta;serializeJson(j,meta);if(!ArchiveFormat::fits(freeBytes(),n,meta.length(),RESERVE)){lost_++;return false;}Header h{MAGIC,(uint32_t)n,crc32(data,n),(uint32_t)meta.length()};String tmp=path(r.id)+".tmp";File f=LittleFS.open(tmp,"w");if(!f){lost_++;return false;}bool ok=f.write((uint8_t*)&h,sizeof h)==sizeof h&&f.write((uint8_t*)meta.c_str(),meta.length())==meta.length()&&f.write(data,n)==n;f.flush();f.close();if(!ok){LittleFS.remove(tmp);lost_++;return false;}File marker=LittleFS.open(queuePath(r.id),"w");if(!marker){LittleFS.remove(tmp);lost_++;return false;}marker.close();if(!LittleFS.rename(tmp,path(r.id))){LittleFS.remove(tmp);LittleFS.remove(queuePath(r.id));lost_++;return false;}return true;}
bool CaptureStorage::readMeta(const String& id,CaptureRecord& r){if(!validId(id))return false;File f=LittleFS.open(path(id),"r");Header h;if(!f||f.readBytes((char*)&h,sizeof h)!=sizeof h||h.magic!=MAGIC||!h.length||h.length>32768||h.metaLength>2048||f.size()!=sizeof h+h.metaLength+h.length)return false;String m;for(uint32_t i=0;i<h.metaLength;i++){int c=f.read();if(c<0)return false;m+=(char)c;}std::vector<uint8_t> b(h.length);if(f.read(b.data(),b.size())!=b.size()||crc32(b.data(),b.size())!=h.crc)return false;JsonDocument j;if(deserializeJson(j,m)||j["id"].as<String>()!=id)return false;r.id=id;r.ip=j["ip"].as<String>();r.port=j["port"]|0;r.timestamp=j["timestamp"].as<uint64_t>();r.format=j["format"].as<String>();r.text=j["text"].as<String>();r.bytes=h.length;r.incomplete=j["incomplete"]|false;r.uploaded=!LittleFS.exists(queuePath(id));return true;}
std::vector<CaptureRecord> CaptureStorage::list(const char* dir,const char* suffix,size_t limit){std::vector<CaptureRecord> v;File d=LittleFS.open(dir);File f=d.openNextFile();while(f){String name=f.name();f=d.openNextFile();if(!name.endsWith(suffix))continue;String id=name.substring(name.lastIndexOf('/')+1,name.length()-strlen(suffix));CaptureRecord r;if(readMeta(id,r))v.push_back(r);}std::sort(v.begin(),v.end(),[](const auto&a,const auto&b){return a.timestamp==b.timestamp?a.id>b.id:a.timestamp>b.timestamp;});if(v.size()>limit)v.resize(limit);return v;}
std::vector<CaptureRecord> CaptureStorage::history(size_t limit){return list("/a",".rec",limit);}
std::vector<CaptureRecord> CaptureStorage::uploadQueue(size_t limit){return list("/q",".pending",limit);}
bool CaptureStorage::raw(const String& id,std::vector<uint8_t>& out){CaptureRecord r;if(!readMeta(id,r))return false;File f=LittleFS.open(path(id),"r");Header h;if(f.readBytes((char*)&h,sizeof h)!=sizeof h||!f.seek(sizeof h+h.metaLength))return false;std::vector<uint8_t> bytes(h.length);if(f.read(bytes.data(),bytes.size())!=bytes.size()||crc32(bytes.data(),bytes.size())!=h.crc)return false;out.swap(bytes);return true;}
bool CaptureStorage::acknowledge(const String& id){CaptureRecord r;if(!readMeta(id,r)||!LittleFS.exists(queuePath(id)))return false;return LittleFS.remove(queuePath(id));}
size_t CaptureStorage::pending(){File d=LittleFS.open("/q");File f=d.openNextFile();size_t count=0;while(f){String name=f.name();f=d.openNextFile();if(name.endsWith(".pending"))count++;}return count;}
